files.content:
'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['summarizeReadings']);
assert.strictEqual(typeof api.summarizeReadings, 'function');

assert.deepStrictEqual(api.summarizeReadings([]), { count: 0, total: 0 });
assert.deepStrictEqual(api.summarizeReadings([1, 2, 3]), { count: 3, total: 6 });
assert.deepStrictEqual(api.summarizeReadings([1.5, -2, 0.25, 0]), {
  count: 4,
  total: -0.25
});

const readings = [10, -3, 4, 4];
const snapshot = readings.slice();
assert.deepStrictEqual(api.summarizeReadings(readings), { count: 4, total: 15 });
assert.deepStrictEqual(readings, snapshot);
assert.strictEqual(Object.prototype.hasOwnProperty.call(globalThis, 'total'), false);

for (const invalid of [
  null,
  undefined,
  {},
  '1,2',
  [1, '2'],
  [NaN],
  [Infinity],
  [-Infinity],
  [1, null],
  [1, undefined]
]) {
  assert.throws(() => api.summarizeReadings(invalid), TypeError);
}

